// ════════════════════════════════════════════════════════════════════
//  วัด "ท่อส่งภาพจากหน้าจอไป Rust" — เครื่องมือวัด ยังไม่ใช่ตัวอัดคลิป
//
//      THAISCORE_SELFTEST_PIPE=1  แล้วเปิดแอป  (ดู src-tauri/src/framepipe.rs)
//
//  ★ คำถามเดียวที่ต้องตอบ: คลิป 3 นาที 30 fps = ภาพ 5,400 ใบ — ส่งผ่าน IPC
//    ของ Tauri ไหวไหม และทางไหนเร็วที่สุด · ถ้าท่อแคบ ตัวอัดต้องออกแบบต่างไปทั้งก้อน
//  ★ วัดจากของจริงในแอปจริง ไม่ใช่ probe ข้างนอก — IPC เป็นของ Tauri ล้วน ๆ
//    probe ข้างนอกจำลองไม่ได้
// ════════════════════════════════════════════════════════════════════
import { invoke } from '@tauri-apps/api/core';

const report = (msg: string) => { void invoke('selftest_report', { msg }).catch(() => {}); };

/** วาดของที่ "หน้าตาเหมือนแผ่นโน้ต" — ★ ขนาดไฟล์ JPEG ขึ้นกับเนื้อภาพ
 *  วาดสี่เหลี่ยมสีเทาจะได้ไฟล์เล็กผิดปกติแล้วสรุปเพี้ยนทั้งชุด */
function paintScore(ctx: CanvasRenderingContext2D, w: number, h: number, seed: number) {
  ctx.fillStyle = '#fffdf7';
  ctx.fillRect(0, 0, w, h);
  ctx.strokeStyle = '#2a2118';
  ctx.fillStyle = '#2a2118';
  const rows = Math.floor(h / 90);
  for (let r = 0; r < rows; r += 1) {
    const y = 60 + r * 90;
    ctx.lineWidth = 1;
    for (let k = 0; k < 5; k += 1) {
      ctx.beginPath(); ctx.moveTo(40, y + k * 7); ctx.lineTo(w - 40, y + k * 7); ctx.stroke();
    }
    // หัวโน้ต + ก้าน — ของที่ทำให้ภาพมีรายละเอียดจริง
    for (let c = 0; c < 16; c += 1) {
      const x = 60 + c * ((w - 120) / 16);
      const yy = y + ((c + r + seed) % 5) * 7;
      ctx.beginPath(); ctx.ellipse(x, yy, 6, 4.5, -0.3, 0, Math.PI * 2); ctx.fill();
      ctx.lineWidth = 1.6;
      ctx.beginPath(); ctx.moveTo(x + 6, yy); ctx.lineTo(x + 6, yy - 26); ctx.stroke();
    }
    ctx.font = '16px sans-serif';
    ctx.fillText(`ท่อน ${r + 1} · ห้อง ${seed}`, 40, y - 14);
  }
}

const blobBytes = (cv: HTMLCanvasElement, type: string, q?: number) =>
  new Promise<Uint8Array>((res, rej) => {
    cv.toBlob((b) => {
      if (!b) { rej(new Error('toBlob คืนค่าว่าง')); return; }
      b.arrayBuffer().then((ab) => res(new Uint8Array(ab)), rej);
    }, type, q);
  });

const ms = (n: number) => n.toFixed(1);
/** เวลาที่ต้องรอจริงสำหรับคลิป 3 นาที (5,400 ใบ) */
const forClip = (perFrame: number) => `${((perFrame * 5400) / 60000).toFixed(1)} นาที`;

/** ★★ กันรันซ้อน — `React.StrictMode` เรียก effect **สองรอบ** ตอน dev ★★
 *  รอบแรกที่วัด (2026-08-19) จึงมี bench สองตัวแย่ CPU กันเอง แล้วได้ตัวเลขที่
 *  **ขัดกันเอง**: ส่ง JPEG 0.32 MB ช้ากว่าส่งพิกเซลดิบ 7.91 MB ซึ่งเป็นไปไม่ได้
 *  → ตัวเลขที่วัดตอนมีงานอื่นแย่งเครื่องอยู่ ใช้ตัดสินสถาปัตยกรรมไม่ได้เลย */
let started = false;

export async function runPipeBench(mode = '1') {
  if (started) { report('(ข้ามรอบซ้ำของ StrictMode)'); return; }
  started = true;
  // ★ โหมด samples = ข้ามการวัดท่อทั้งชุด ไปทำคลิปตัวอย่างอย่างเดียว
  if (mode.startsWith('samples')) {
    const { runRasterBench } = await import('./raster_bench');
    await runRasterBench(mode);
    return;
  }
  report('══ วัดท่อส่งภาพหน้าจอ→Rust · คลิป 3 นาที = 5,400 ใบ ══');
  await invoke('pipe_reset').catch(() => {});

  const SIZES: Array<[number, number, string]> = [
    [720, 1280, '720p แนวตั้ง'],
    [1080, 1920, '1080p แนวตั้ง'],
  ];
  const N = 20;   // ใบต่อหนึ่งการวัด — พอให้ค่าเฉลี่ยนิ่ง โดยไม่ทำให้รอนาน

  for (const [w, h, label] of SIZES) {
    const cv = document.createElement('canvas');
    cv.width = w; cv.height = h;
    const ctx = cv.getContext('2d', { willReadFrequently: true })!;

    // ── ๑ ปั้นไบต์ (ยังไม่ส่ง) — ราคาฝั่งหน้าจอล้วน ๆ ──────────────
    const kinds: Array<[string, () => Promise<Uint8Array>]> = [
      ['พิกเซลดิบ RGBA', async () => new Uint8Array(ctx.getImageData(0, 0, w, h).data.buffer)],
      ['JPEG q0.8', () => blobBytes(cv, 'image/jpeg', 0.8)],
      ['PNG', () => blobBytes(cv, 'image/png')],
    ];

    for (const [kname, make] of kinds) {
      const P: number[] = []; const S: number[] = []; const D: number[] = [];
      let bytes = 0;
      // ★ อุ่นเครื่อง 3 ใบก่อนเริ่มจับเวลา — ใบแรก ๆ กินเวลาจัดสรรหน่วยความจำ
      //   และ JIT ซึ่งไม่ใช่ราคาที่ผู้ใช้จ่ายจริงตลอดคลิป 5,400 ใบ
      for (let i = 0; i < N + 3; i += 1) {
        paintScore(ctx, w, h, i);
        const t0 = performance.now();
        const buf = await make();
        const t1 = performance.now();
        // ★ ต้องส่ง **สำเนา** ทุกใบ — ArrayBuffer ถูก transfer ไปแล้วใช้ซ้ำไม่ได้
        await invoke('pipe_raw', buf.slice());
        const t2 = performance.now();
        await invoke<number>('pipe_raw_file', buf.slice());
        const t3 = performance.now();
        bytes = buf.length;
        if (i < 3) continue;
        P.push(t1 - t0); S.push(t2 - t1); D.push(t3 - t2);
      }
      // ★ ค่ากลาง ไม่ใช่ค่าเฉลี่ย — ใบเดียวที่โดน GC ขวางดึงค่าเฉลี่ยเพี้ยนทั้งชุด
      const mid = (a: number[]) => [...a].sort((x, y) => x - y)[Math.floor(a.length / 2)];
      const p = mid(P); const s = mid(S); const d = mid(D);
      const mb = bytes / 1048576;
      report(
        `${label} · ${kname}: ${mb.toFixed(2)} MB/ใบ · ปั้น ${ms(p)} ms · ส่ง ${ms(s)} ms `
        + `(${(mb / (s / 1000)).toFixed(0)} MB/วิ) · ส่ง+เขียนดิสก์ ${ms(d)} ms`,
      );
      report(
        `   └ รวมทางที่เร็วสุด ${ms(p + s)} ms/ใบ → คลิป 3 นาทีรอ ${forClip(p + s)}`
        + ` · ถ้าเขียนดิสก์ด้วย ${ms(p + d)} ms/ใบ → ${forClip(p + d)}`,
      );
    }
  }

  // ── ๒ ทางที่เลือกผิดแล้วราคาแพงแค่ไหน (อาเรย์ตัวเลขใน JSON) ────────
  //   ★ ใช้ภาพเล็กมากเท่านั้น — 1080p ทางนี้กินเวลาเป็นนาทีต่อใบเดียว
  {
    const cv = document.createElement('canvas');
    cv.width = 320; cv.height = 180;
    const ctx = cv.getContext('2d')!;
    paintScore(ctx, 320, 180, 1);
    const buf = await blobBytes(cv, 'image/jpeg', 0.8);
    const t0 = performance.now();
    for (let i = 0; i < 5; i += 1) await invoke('pipe_json', { bytes: Array.from(buf) });
    const jsonMs = (performance.now() - t0) / 5;
    const t1 = performance.now();
    for (let i = 0; i < 5; i += 1) await invoke('pipe_raw', buf.slice());
    const rawMs = (performance.now() - t1) / 5;
    report(
      `เทียบทาง (ภาพเล็ก ${(buf.length / 1024).toFixed(0)} KB): ข้อมูลดิบ ${ms(rawMs)} ms `
      + `· อาเรย์ตัวเลขใน JSON ${ms(jsonMs)} ms = ช้ากว่า ${(jsonMs / rawMs).toFixed(0)} เท่า`,
    );
  }

  await invoke('pipe_reset').catch(() => {});
  report('══ วัดท่อเสร็จ ══');

  // ── ๓ ฝั่งวาด (กระดาษบนจอ → ภาพ) — อีกครึ่งของราคาต่อเฟรม ──────────
  const { runRasterBench } = await import('./raster_bench');
  await runRasterBench('1');
}
